import pytest


class BadInput(Exception):
    def __init__(self, text: str) -> None:
        self.text: str = text


def sum_parsed(xs: list[str]) -> int:
    """Parse every string in xs as an integer and return their sum.

    Raises BadInput carrying the first string that is not an integer.
    """
    total: int = 0
    for text in xs:
        try:
            total += int(text)
        except ValueError:
            raise BadInput(text) from None
    return total


def test_sum_parsed_basic() -> None:
    assert sum_parsed(["1", "2", "3"]) == 6


def test_sum_parsed_negatives() -> None:
    assert sum_parsed(["-5", "10", "-2"]) == 3


def test_sum_parsed_empty() -> None:
    assert sum_parsed([]) == 0


def test_sum_parsed_bad_input_carries_text() -> None:
    with pytest.raises(BadInput) as info:
        sum_parsed(["1", "x", "y"])
    assert info.value.text == "x"


def test_sum_parsed_reports_first_bad_only() -> None:
    with pytest.raises(BadInput) as info:
        sum_parsed(["4", "1.5", "oops"])
    assert info.value.text == "1.5"
